-- Make trial a one-time canteen activation property and enforce configured plan billing server-side.
create or replace function public.sync_subscription_statuses(p_canteen_id uuid default null) returns void language plpgsql security definer set search_path='' as $$ declare v_uid uuid:=auth.uid(); v_allowed boolean:=false; v_sub public.canteen_subscriptions; v_next_plan_id uuid; begin if v_uid is null then raise exception 'Authentication required'; end if; if public.is_super_admin() then v_allowed:=true; elsif p_canteen_id is not null and public.current_canteen_id()=p_canteen_id then v_allowed:=true; end if; if not v_allowed then raise exception 'Not authorized'; end if; for v_sub in select * from public.canteen_subscriptions where (p_canteen_id is null or canteen_id=p_canteen_id) and ((status='trial' and trial_end is not null and trial_end<=now()) or (status='active' and subscription_end is not null and subscription_end<=now())) for update loop if v_sub.status='trial' then update public.canteen_subscriptions set status='suspended',payment_status='pending',updated_at=now() where id=v_sub.id; else if v_sub.plan_selection_mode='auto_range' then v_next_plan_id:=public.resolve_member_range_plan(v_sub.canteen_id); else v_next_plan_id:=v_sub.plan_id; end if; update public.canteen_subscriptions set plan_id=coalesce(v_next_plan_id,v_sub.plan_id),status='expired',payment_status='pending',updated_at=now() where id=v_sub.id; end if; end loop; end $$;
create or replace function public.super_admin_set_subscription(p_canteen_id uuid,p_action text,p_plan_id uuid default null,p_trial_days integer default null,p_amount numeric default null,p_currency text default null,p_billing_cycle text default 'monthly',p_plan_selection_mode text default null) returns public.canteen_subscriptions language plpgsql security definer set search_path='' as $$ declare v_sub public.canteen_subscriptions; v_plan public.subscription_plans; v_plan_id uuid; v_now timestamptz:=now(); v_trial_days integer; v_cycle text; v_mode text; v_start timestamptz; v_end timestamptz; v_override numeric(12,2); begin if not public.is_super_admin() then raise exception 'Super Admin authorization required'; end if; if exists(select 1 from public.canteens c where c.id=p_canteen_id and (c.name='GoCanteen' or c.owner_id=(select id from public.profiles where id=(select auth.uid()) and admin_role='super_admin'))) then raise exception 'Super Admin platform canteen is not a customer subscription'; end if; if not exists(select 1 from public.canteens c where c.id=p_canteen_id) then raise exception 'Canteen not found'; end if; select * into v_sub from public.canteen_subscriptions where canteen_id=p_canteen_id for update; if p_action in ('activate_trial','activate') then if v_sub.id is not null then if v_sub.trial_used_at is not null then raise exception 'This canteen has already used its initial activation decision. Use Change Plan or Renewal instead.'; end if; if v_sub.status not in ('payment_pending','trial') then raise exception 'This canteen is already activated. Use Change Plan instead.'; end if; end if; if p_plan_id is null then v_plan_id:=public.resolve_member_range_plan(p_canteen_id); if v_plan_id is null then raise exception 'A configured MEMBER_RANGE plan does not match the current member count'; end if; else v_plan_id:=p_plan_id; end if; select * into v_plan from public.subscription_plans where id=v_plan_id and active=true; if not found then raise exception 'Selected plan not found or inactive'; end if; v_cycle:=case when v_plan.pricing_model='FIXED_AMOUNT' then 'monthly' else v_plan.billing_cycle end; v_mode:=case when v_plan.pricing_model='MEMBER_RANGE' and p_plan_selection_mode='auto_range' then 'auto_range' else 'manual' end; v_override:=case when v_plan.pricing_model='FIXED_AMOUNT' then nullif(p_amount,0) else null end; if v_override is not null and v_override<0 then raise exception 'Effective amount cannot be negative'; end if; if p_action='activate_trial' then v_trial_days:=coalesce(p_trial_days,0); if v_trial_days<=0 then raise exception 'Trial duration must be greater than zero when trial is enabled'; end if; v_now:=now(); insert into public.canteen_subscriptions(canteen_id,plan_id,status,trial_start,trial_end,subscription_start,subscription_end,amount,currency,payment_status,billing_cycle,plan_selection_mode,trial_used_at,effective_amount_override) values(p_canteen_id,v_plan_id,'trial',v_now,v_now+make_interval(days=>v_trial_days),null,null,case when v_plan.pricing_model='FIXED_AMOUNT' then coalesce(v_override,v_plan.monthly_price) else v_plan.monthly_price end,coalesce(p_currency,v_plan.currency),'pending',v_cycle,v_mode,v_now,v_override) on conflict(canteen_id) do update set plan_id=excluded.plan_id,status='trial',trial_start=excluded.trial_start,trial_end=excluded.trial_end,subscription_start=null,subscription_end=null,amount=excluded.amount,currency=excluded.currency,payment_status='pending',billing_cycle=excluded.billing_cycle,plan_selection_mode=excluded.plan_selection_mode,trial_used_at=coalesce(public.canteen_subscriptions.trial_used_at,excluded.trial_used_at),effective_amount_override=excluded.effective_amount_override,updated_at=now() returning * into v_sub; return v_sub; end if; v_start:=coalesce(v_sub.subscription_start,v_now); v_end:=case when v_cycle='annual' then v_start+interval '1 year' else v_start+interval '1 month' end; insert into public.canteen_subscriptions(canteen_id,plan_id,status,trial_start,trial_end,subscription_start,subscription_end,amount,currency,payment_status,billing_cycle,plan_selection_mode,trial_used_at,effective_amount_override) values(p_canteen_id,v_plan_id,'active',coalesce(v_sub.trial_start,null),coalesce(v_sub.trial_end,null),v_start,v_end,case when v_plan.pricing_model='FIXED_AMOUNT' then coalesce(v_override,v_plan.monthly_price) when v_cycle='annual' then coalesce((select max(annual_price) from public.subscription_plan_ranges where plan_id=v_plan.id),v_plan.annual_price) else coalesce((select min(monthly_price) from public.subscription_plan_ranges where plan_id=v_plan.id),v_plan.monthly_price) end,coalesce(p_currency,v_plan.currency),'paid',v_cycle,v_mode,coalesce(v_sub.trial_used_at,v_now),v_override) on conflict(canteen_id) do update set plan_id=excluded.plan_id,status='active',subscription_start=excluded.subscription_start,subscription_end=excluded.subscription_end,amount=excluded.amount,currency=excluded.currency,payment_status='paid',billing_cycle=excluded.billing_cycle,plan_selection_mode=excluded.plan_selection_mode,trial_used_at=coalesce(public.canteen_subscriptions.trial_used_at,excluded.trial_used_at),effective_amount_override=excluded.effective_amount_override,updated_at=now() returning * into v_sub; return v_sub; end if; if p_action='extend_trial' then if v_sub.id is null then raise exception 'Subscription not found'; end if; raise exception 'Trial extension is not supported. The initial trial is a one-time activation property.'; end if; if p_action='change_plan' then if v_sub.id is null then raise exception 'Subscription not found'; end if; if p_plan_id is null then raise exception 'Plan is required'; end if; select * into v_plan from public.subscription_plans where id=p_plan_id and active=true; if not found then raise exception 'Selected plan not found or inactive'; end if; v_cycle:=case when v_plan.pricing_model='FIXED_AMOUNT' then 'monthly' else v_plan.billing_cycle end; v_mode:='manual'; v_override:=case when v_plan.pricing_model='FIXED_AMOUNT' then p_amount else null end; if v_override is not null and v_override<0 then raise exception 'Effective amount cannot be negative'; end if; update public.canteen_subscriptions set plan_id=v_plan.id,billing_cycle=v_cycle,plan_selection_mode=v_mode,effective_amount_override=v_override,updated_at=now() where id=v_sub.id returning * into v_sub; return v_sub; end if; if p_action='suspend' then if v_sub.id is null then raise exception 'Subscription not found'; end if; update public.canteen_subscriptions set status='suspended',updated_at=now() where id=v_sub.id returning * into v_sub; return v_sub; end if; if p_action='payment_pending' then if v_sub.id is null then raise exception 'Subscription not found'; end if; update public.canteen_subscriptions set payment_status='pending',updated_at=now() where id=v_sub.id returning * into v_sub; return v_sub; end if; raise exception 'Unsupported subscription action'; end $$;
create or replace function public.canteen_create_subscription_payment(p_subscription_id uuid,p_billing_cycle text,p_payment_date date,p_reference text,p_note text default null,p_payment_method_id uuid default null) returns public.subscription_payments language plpgsql security definer set search_path='' as $$ declare s public.canteen_subscriptions; p public.subscription_plans; m public.subscription_payment_methods; outp public.subscription_payments; period jsonb; quote jsonb; expected numeric(12,2); v_cycle text; v_payment_type text; begin if auth.uid() is null or not public.is_active_canteen_admin() then raise exception 'Canteen Admin authorization required'; end if; select * into s from public.canteen_subscriptions where id=p_subscription_id and canteen_id=public.current_canteen_id() for update; if not found then raise exception 'Subscription not found'; end if; if s.status not in ('trial','active','payment_pending','expired','suspended') then raise exception 'Payment is not currently required for this subscription'; end if; if nullif(trim(coalesce(p_reference,'')),'') is null or p_payment_date is null then raise exception 'Payment details are required'; end if; if exists(select 1 from public.subscription_payments where subscription_id=s.id and payment_status='pending' and payment_type<>'plan_upgrade') then raise exception 'A payment is already pending review for this subscription'; end if; quote:=public.get_subscription_billing_quote(s.canteen_id); if coalesce((quote->>'required')::boolean,false)=false then raise exception '%',coalesce(quote->>'message','Subscription pricing is not currently configured.'); end if; v_cycle:=quote->>'billing_cycle'; if p_billing_cycle<>v_cycle then raise exception 'Billing cycle is configured by the administrator and cannot be changed by the customer'; end if; expected:=(quote->>'amount')::numeric; select * into p from public.subscription_plans where id=(quote->>'plan_id')::uuid and active=true; if not found then raise exception 'Active subscription plan not found'; end if; select * into m from public.subscription_payment_methods where id=coalesce(p_payment_method_id,(select id from public.subscription_payment_methods where active and is_default limit 1)) and active; if not found then raise exception 'No active payment method is configured'; end if; period:=public.resolve_subscription_billing_period(s.id,v_cycle); v_payment_type:=case when s.status='active' then 'renewal' else 'subscription' end; insert into public.subscription_payments(canteen_id,subscription_id,plan_id,amount,currency,payment_date,payment_status,transaction_reference,payment_provider,payment_note,billing_cycle,payment_type,billing_period_start,billing_period_end,payment_method_id,payment_method_reference,payment_method_snapshot) values(s.canteen_id,s.id,p.id,expected,p.currency,p_payment_date::timestamptz,'pending',trim(p_reference),m.provider,nullif(trim(coalesce(p_note,'')),''),v_cycle,v_payment_type,(period->>'billing_period_start')::timestamptz,(period->>'billing_period_end')::timestamptz,m.id,coalesce(m.upi_id,m.display_name),jsonb_build_object('id',m.id,'provider',m.provider,'method_type',m.method_type,'display_name',m.display_name,'upi_id',m.upi_id)) returning * into outp; update public.canteen_subscriptions set payment_status='pending',updated_at=now() where id=s.id; return outp; end $$;
create or replace function public.super_admin_review_subscription_payment(p_payment_id uuid,p_status text,p_billing_cycle text default null) returns public.subscription_payments language plpgsql security definer set search_path='' as $$ declare pay public.subscription_payments; s public.canteen_subscriptions; p public.subscription_plans; q jsonb; cycle text; start_at timestamptz; end_at timestamptz; expected numeric(12,2); begin if not public.is_super_admin() then raise exception 'Super Admin authorization required'; end if; if p_status not in ('paid','failed') then raise exception 'Review status must be paid or failed'; end if; select * into pay from public.subscription_payments where id=p_payment_id for update; if not found then raise exception 'Payment not found'; end if; if pay.payment_status<>'pending' then raise exception 'Only pending payments can be reviewed'; end if; select * into s from public.canteen_subscriptions where id=pay.subscription_id for update; if not found then raise exception 'Subscription not found'; end if; if p_status='failed' then update public.subscription_payments set payment_status='failed',updated_at=now() where id=pay.id returning * into pay; update public.canteen_subscriptions set payment_status='failed',updated_at=now() where id=s.id; return pay; end if; if pay.payment_type='plan_upgrade' then select * into p from public.subscription_plans where id=pay.plan_id and active=true; if not found then raise exception 'Upgrade plan is not active'; end if; if s.status<>'active' or s.billing_cycle<>'annual' then raise exception 'Annual subscription is required for this upgrade'; end if; q:=public.get_subscription_upgrade_quote(s.canteen_id,p.id); expected:=coalesce((q->>'additional_amount')::numeric,0); if round(pay.amount,2)<>round(expected,2) or expected<=0 then raise exception 'Upgrade payment amount no longer matches the authoritative calculation'; end if; update public.subscription_payments set payment_status='paid',billing_period_start=s.subscription_start,billing_period_end=s.subscription_end,updated_at=now() where id=pay.id returning * into pay; update public.canteen_subscriptions set plan_id=p.id,amount=case when p.pricing_model='FIXED_AMOUNT' then p.monthly_price else p.annual_price end,status='active',payment_status='paid',updated_at=now() where id=s.id; return pay; end if; cycle:=coalesce(pay.billing_cycle,s.billing_cycle); if cycle not in ('monthly','annual') then raise exception 'Billing cycle must be monthly or annual'; end if; select * into p from public.subscription_plans where id=pay.plan_id and active=true; if not found then raise exception 'Active subscription plan not found'; end if; q:=public.get_subscription_billing_quote(s.canteen_id); if coalesce((q->>'required')::boolean,false)=false then raise exception '%',coalesce(q->>'message','Subscription pricing is not currently configured.'); end if; if (q->>'billing_cycle')<>cycle then raise exception 'The configured billing cycle changed after payment submission'; end if; expected:=(q->>'amount')::numeric; if round(pay.amount,2)<>round(expected,2) then raise exception 'Verified payment amount does not match the current configured subscription price'; end if; start_at:=pay.billing_period_start; end_at:=pay.billing_period_end; if start_at is null or end_at is null then q:=public.resolve_subscription_billing_period(s.id,cycle); start_at:=(q->>'billing_period_start')::timestamptz; end_at:=(q->>'billing_period_end')::timestamptz; end if; update public.subscription_payments set payment_status='paid',billing_cycle=cycle,billing_period_start=start_at,billing_period_end=end_at,updated_at=now() where id=pay.id returning * into pay; update public.canteen_subscriptions set plan_id=pay.plan_id,billing_cycle=cycle,status='active',payment_status='paid',subscription_start=start_at,subscription_end=end_at,amount=expected,currency=p.currency,updated_at=now() where id=s.id; return pay; end $$;
create or replace function public.get_subscription_upgrade_quote(p_canteen_id uuid,p_new_plan_id uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_uid uuid:=auth.uid(); v_sub public.canteen_subscriptions; v_old public.subscription_plans; v_new public.subscription_plans; v_new_id uuid; v_members integer; v_remaining integer; v_old_monthly numeric(12,2); v_new_monthly numeric(12,2); v_diff numeric(12,2); v_amount numeric(12,2); begin if v_uid is null then raise exception 'Authentication required'; end if; if not(public.is_super_admin() or public.current_canteen_id()=p_canteen_id) then raise exception 'Not authorized'; end if; select * into v_sub from public.canteen_subscriptions where canteen_id=p_canteen_id; if not found then raise exception 'Subscription not found'; end if; if v_sub.status<>'active' or v_sub.billing_cycle<>'annual' then return jsonb_build_object('required',false,'reason','upgrade_only_applies_to_active_annual_subscriptions'); end if; select * into v_old from public.subscription_plans where id=v_sub.plan_id; if not found then raise exception 'Current plan not found'; end if; v_members:=(select count(*)::integer from public.profiles e where e.canteen_id=p_canteen_id and e.role='employee' and e.status='active'); v_new_id:=coalesce(p_new_plan_id,case when v_sub.plan_selection_mode='auto_range' then public.resolve_member_range_plan(p_canteen_id) else null end); if v_new_id is null or v_new_id=v_old.id then return jsonb_build_object('required',false,'active_members',v_members,'current_plan_id',v_old.id); end if; select * into v_new from public.subscription_plans where id=v_new_id and active=true; if not found then raise exception 'New plan not found'; end if; if v_new.pricing_model<>'MEMBER_RANGE' then return jsonb_build_object('required',false,'active_members',v_members,'reason','new_plan_not_member_range'); end if; select greatest(0,count(*)::integer) into v_remaining from generate_series(1,120) g(n) where now()+(g.n*interval '1 month')<v_sub.subscription_end; if v_old.pricing_model='MEMBER_RANGE' then select case when v_sub.billing_cycle='annual' then r.annual_price else r.monthly_price end into v_old_monthly from public.subscription_plan_ranges r where r.plan_id=v_old.id and r.min_members<=v_members and r.max_members>=v_members order by r.min_members desc limit 1; end if; v_old_monthly:=coalesce(v_old_monthly,v_old.monthly_price); if v_new.pricing_model='MEMBER_RANGE' then select case when v_sub.billing_cycle='annual' then r.annual_price else r.monthly_price end into v_new_monthly from public.subscription_plan_ranges r where r.plan_id=v_new.id and r.min_members<=v_members and r.max_members>=v_members order by r.min_members desc limit 1; end if; v_new_monthly:=coalesce(v_new_monthly,v_new.monthly_price); if v_sub.billing_cycle='annual' then v_old_monthly:=coalesce(v_old_monthly/12,v_old.monthly_price); v_new_monthly:=coalesce(v_new_monthly/12,v_new.annual_price/12); end if; v_diff:=round(v_new_monthly-v_old_monthly,2); v_amount:=greatest(0,round(v_diff*v_remaining,2)); return jsonb_build_object('required',v_amount>0,'active_members',v_members,'current_plan_id',v_old.id,'current_plan_name',v_old.name,'current_monthly_equivalent',v_old_monthly,'new_plan_id',v_new.id,'new_plan_name',v_new.name,'new_monthly_equivalent',v_new_monthly,'monthly_difference',v_diff,'remaining_full_months',v_remaining,'additional_amount',v_amount,'currency',v_new.currency,'original_subscription_start',v_sub.subscription_start,'original_subscription_end',v_sub.subscription_end); end $$;
revoke execute on function public.get_subscription_billing_quote(uuid) from public,anon;
grant execute on function public.get_subscription_billing_quote(uuid) to authenticated;
